import { DomainError, isPaymentMethod } from "@delulu/core";
import { issuePaymentChallenge } from "@delulu/db/runtime";
import { trackAfter } from "@/server/analytics";
import { payPool } from "@/server/db";
import { pathId, route } from "@/server/http";
import { RATE_RULES } from "@/server/rate-limit";

/**
 * POST /api/v1/checkout-sessions/{id}/challenge: sends the bank step of the session's pending NET_BANKING
 * (a six-digit code) or DELULUPAY_ID (an approval request) attempt to the payer's in-app bank inbox. The
 * code is generated by the server, valid three minutes and never in this response: read it in the inbox
 * (GET /api/v1/bank/inbox). A new one may be asked for 30 seconds later; five an hour per account. No SMS,
 * email or push message ever carries it (PRD R4.4). Records `payment_challenge_issued` (the method only).
 */
export const POST = route(
  { auth: "session", rateLimits: [{ rule: RATE_RULES.challengeIssueActor }] },
  async ({ request, session, params }) => {
    const analytics = { surface: "checkout", authSessionId: session.id } as const;
    try {
      const issued = await issuePaymentChallenge(payPool(), {
        authSessionId: session.id,
        sessionId: pathId(params),
      });
      trackAfter(request, "payment_challenge_issued", { method: issued.method }, analytics);
      return {
        status: 201,
        json: {
          attemptId: issued.attemptId,
          reference: issued.reference,
          method: issued.method,
          kind: issued.kind,
          expiresAt: issued.expiresAt,
          resendAfterSeconds: issued.resendAfterSeconds,
          availableAt: issued.availableAt,
        },
      };
    } catch (error) {
      const method = error instanceof DomainError ? error.details.method : undefined;
      if (isPaymentMethod(method)) trackAfter(request, "payment_challenge_failed", { method }, analytics);
      throw error;
    }
  },
);
